#[cfg(test)]
mod tests {
    use super::translate;

    #[test]
    fn translates_static_and_dynamic_ui_without_touching_shortcuts() {
        assert_eq!(translate("Sandbox"), "沙盒");
        assert_eq!(translate("Finished Trips: 12"), "已完成行程：12");
        assert_eq!(translate("save scenario"), "保存场景");
        assert_eq!(translate("Ctrl+X"), "Ctrl+X");
    }
}
